var plan=System.Text.Json.Nodes.JsonNode.Parse(System.IO.File.ReadAllText("C:\\Users\\mimi-\\AppData\\Local\\Temp\\sbox-cli\\7751bfe156d740d7ada3f1d6cd94736d/width-plan.json")).AsArray();var session=Editor.SceneEditorSession.Active;var scene=session.Scene;var objects=scene.GetAllObjects(true).ToDictionary(x=>x.Id);var changes=new System.Collections.Generic.List<(GameObject Go,Vector3 Scale)>();foreach(var row in plan){var go=objects[Guid.Parse(row["id"].GetValue<string>())];if(go.Name!=row["name"].GetValue<string>())throw new Exception("Tree identity mismatch");var a=row["before"].AsArray().Select(x=>x.GetValue<float>()).ToArray();var b=row["after"].AsArray().Select(x=>x.GetValue<float>()).ToArray();if((go.WorldScale-new Vector3(a[0],a[1],a[2])).Length>.001f)throw new Exception("Tree scale changed: "+go.Name);changes.Add((go,new Vector3(b[0],b[1],b[2])));}if(changes.Count!=444)throw new Exception("Unexpected canopy count");foreach(var c in changes)c.Go.WorldScale=c.Scale;session.HasUnsavedChanges=true;return new{Changed=changes.Count,Scene=scene.Name,Dirty=session.HasUnsavedChanges};